package com.enfec.one.asset.workflow;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="goods_receipts") public class GoodsReceipt { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="request_id",nullable=false) private UUID requestId; @Column(name="po_id") private UUID poId; @Column(name="grn_number",nullable=false,unique=true,length=100) private String grnNumber; @Column(nullable=false) private Integer receivedQuantity; @Column(length=100) private String condition; @Column(name="received_at",nullable=false) private OffsetDateTime receivedAt; @Column(nullable=false) private boolean inspected=false; @Column(length=2000) private String notes; protected GoodsReceipt(){} public GoodsReceipt(UUID r,UUID p,String n,Integer q,String c,String notes){requestId=r;poId=p;grnNumber=n;receivedQuantity=q;condition=c;this.notes=notes;receivedAt=OffsetDateTime.now(ZoneOffset.UTC);} public void inspect(){inspected=true;} public UUID getId(){return id;} public String getGrnNumber(){return grnNumber;} public Integer getReceivedQuantity(){return receivedQuantity;} public boolean isInspected(){return inspected;} }
